svg.script:
const svg = document.documentElement;
const button = document.getElementById("button");
const status = document.getElementById("status");

/*
 * Create a normal HTML file input dynamically.
 * Nothing HTML is embedded in the SVG itself.
 */
const input = document.createElementNS(
    "http://www.w3.org/1999/xhtml",
    "input"
);

input.type = "file";
input.accept = ".html,.htm,text/html";

/*
 * Keep it invisible.
 */
input.style.position = "fixed";
input.style.left = "-10000px";
input.style.top = "-10000px";

document.body.appendChild(input);


/*
 * Clicking the SVG button opens the normal
 * browser file picker.
 */
button.addEventListener("click", function () {
    input.click();
});


/*
 * User selected an HTML file.
 */
input.addEventListener("change", function () {

    const file = input.files[0];

    if (!file) {
        return;
    }

    status.textContent = "Loading " + file.name + "...";


    /*
     * Turn the selected file into a Blob URL.
     */
    const url = URL.createObjectURL(file);


    /*
     * Replace THIS tab with the HTML document.
     *
     * No new tab.
     * No server.
     * No iframe.
     * No XML/HTML parsing by us.
     */
    window.location.href = url;

});
